$('againBtn').onclick=async()=>{if(matchLocked())return;if(!online){const wasRanked=state?.ranked;setup();practice(!!wasRanked);return;}if(room){playing=false;online=false;document.body.classList.remove('playing');$('hud').hidden=true;modal('resultModal',false);send({type:'returnRoom'});chooseFighter(selected);send({type:'loadout',...loadout()});modal('roomModal',true);renderRoom();}else{closeSocket();setup();setType('online');$('playBtn').onclick();}};$('backBtn').onclick=leaveToMenu;
$('buyHyperBtn').onclick=()=>{if(playing&&!state?.ended)return;const result=E.buyHyper(profile,selected);if(result.ok){save();chooseFighter(selected);$('purchaseStatus').textContent=result.cost?'Hypercharge purchased for '+Z.fighter(selected).name+'.':'Hypercharge already owned.';}else $('purchaseStatus').textContent=result.message;};
$('upgradeBtn').onclick=()=>{if(playing&&!state?.ended)return;const result=E.buyLevel(profile,selected);if(result.ok){save();chooseFighter(selected);$('purchaseStatus').textContent='Level '+result.level+' reached. Eligible abilities are purchased separately.';}else $('purchaseStatus').textContent=result.message;};
function openRoad(){refreshEconomy();$('roadTotal').textContent=profile.roadTrophies+' ROAD TROPHIES · BEST '+profile.roadBest+' · ROAD GOES TO 1,000,000';$('roadRewards').replaceChildren();const road=E.roadFor(profile),claimedAt=profile.roadClaimed*E.ROAD_STEP,visible=road.filter(r=>r.at<=claimedAt).slice(-5).concat(road.filter(r=>r.at>claimedAt).slice(0,30));const label=r=>r.type==='chest'?(r.legendary?'LEGENDARY LOOTBOX':'RANDOM LOOTBOX'):r.type==='mode'?'UNLOCK '+Z.mode(r.mode).name.toUpperCase():r.type==='ranked'?'UNLOCK RANKED':r.type==='fighter'?'FIGHTER · '+Z.fighter(r.fighter).name.toUpperCase():r.amount+' '+r.type.toUpperCase();for(const reward of visible){const done=reward.at<=claimedAt,row=document.createElement('div');row.className='road-reward'+(done?' earned':'')+(reward.legendary||reward.type==='mode'||reward.type==='ranked'||reward.type==='fighter'?' special':'');const at=document.createElement('strong');at.textContent=reward.at.toLocaleString()+' 🏆';const l=document.createElement('span');l.textContent=label(reward);const badge=document.createElement('small');badge.textContent=done?'CLAIMED':Math.max(0,reward.at-profile.roadBest)+' TO GO';row.append(at,l,badge);$('roadRewards').append(row);}save();modal('roadModal',true);}
function paintRecruit(message=''){const offer=E.ensureOffer(profile),target=profile.unlockTarget;$('recruitBank').textContent=profile.credits+' BANKED CREDITS';$('recruitMessage').textContent=message;$('recruitOptions').replaceChildren();$('recruitTarget').hidden=!target;$('recruitTitle').textContent=target?'Your next fighter.':offer?'Choose your next fighter.':'Roster complete.';if(target){const c=Z.fighter(target.fighter),r=E.rarity(c.rarity);$('targetName').textContent=c.name+' · '+r.name;$('targetProgress').textContent=target.progress+' / '+r.credits+' CREDITS';$('targetFill').style.width=100*target.progress/r.credits+'%';$('targetDetail').textContent=c.description;A.portrait($('targetPortrait'),c.id);}else if(offer){const rarity=E.rarity(offer.rarity);$('recruitMessage').textContent=message||'Your random rarity: '+rarity.name+'. Choose one of these fighters. Offers stay saved until you choose.';for(const id of offer.candidates){const c=Z.fighter(id),button=document.createElement('button');button.className='recruit-card';const cv=document.createElement('canvas');cv.width=220;cv.height=125;A.portrait(cv,id);const name=document.createElement('strong');name.textContent=c.name;const role=document.createElement('small');role.textContent=c.role+' · '+rarity.name+' · Mastery '+c.complexity+'/5';const desc=document.createElement('p');desc.textContent=c.description;const price=document.createElement('span');price.textContent='WORK TOWARD · '+rarity.credits+' CREDITS';price.style.color=rarity.color;button.append(cv,name,role,desc,price);button.onclick=()=>{const result=E.chooseUnlock(profile,id);save();refreshEconomy();paintRecruit(result.ok?result.unlocked.length?'Unlocked '+Z.fighter(result.unlocked[0]).name+'! Choose your next target.':'Credits will now go toward '+c.name+'.':result.message);};$('recruitOptions').append(button);}}refreshEconomy();save();}
function openRecruit(){paintRecruit();modal('recruitModal',true);}$('unlockBtn').onclick=openRecruit;$('closeRecruit').onclick=()=>{modal('recruitModal',false);chooseFighter(selected);};
$('roadBtn').onclick=openRoad;$('closeRoad').onclick=()=>modal('roadModal',false);
function paintChest(message=''){refreshEconomy();const c=profile.chests.find(c=>c.id===currentChest),tier=E.RARITIES[c?.tier||0];$('dropTier').textContent=c?tier.name.toUpperCase():'LOOTBOXES';$('dropTier').style.color=tier.color;$('chestButton').style.setProperty('--chestColor',tier.color);$('chestButton').disabled=!c||c.claimed;$('chestButton').classList.toggle('opened',!!c?.claimed);$('chestClicks').replaceChildren();for(let i=0;i<6;i++){const dot=document.createElement('i');dot.className=i<(c?.clicks||0)?'done':'';$('chestClicks').append(dot);}$('dropHint').textContent=c?c.claimed?'Reward added to your collection.':message||'Click the lootbox · '+(6-c.clicks)+' upgrade attempts left':'Earn lootboxes from your first five wins each day, Trophy Road and the Battle Pass.';$('dropReward').textContent=c?.reward?c.reward.type==='coins'?'+'+c.reward.amount+' COINS':c.reward.type==='credits'?'+'+c.reward.amount+' CREDITS'+(c.reward.unlocked?.length?' · '+Z.fighter(c.reward.unlocked[0]).name+' UNLOCKED':''):Z.fighter(c.reward.fighter).name.toUpperCase()+' UNLOCKED':'';$('dropPortrait').hidden=c?.reward?.type!=='fighter';if(c?.reward?.type==='fighter')A.portrait($('dropPortrait'),c.reward.fighter);$('dropDaily').textContent=profile.daily.earned+'/5 win lootboxes earned today · Resets at midnight in Cedarville (Eastern Time)';$('nextDrop').hidden=!c?.claimed;$('nextDrop').textContent=profile.chests.some(q=>!q.claimed)?'OPEN NEXT LOOTBOX':'DONE';}
function openChest(){currentChest=profile.chests.find(c=>!c.claimed)?.id||null;paintChest();modal('dropModal',true);}
$('dropsBtn').onclick=openChest;$('resultDropsBtn').onclick=openChest;$('closeDrop').onclick=()=>{modal('dropModal',false);chooseFighter(selected);};$('nextDrop').onclick=()=>{if(profile.chests.some(c=>!c.claimed))openChest();else $('closeDrop').onclick();};$('chestButton').onclick=()=>{const r=E.clickChest(profile,currentChest);if(!r.ok)return;save();tone(r.upgraded?550:250,.13,'triangle',.08,r.upgraded?250:70);paintChest(r.upgraded?'UPGRADED! '+E.RARITIES[r.chest.tier].name+' · '+(6-r.chest.clicks)+' attempts left':'No upgrade · '+(6-r.chest.clicks)+' attempts left');$('chestButton').animate?.([{transform:'scale(.96) rotate(-2deg)'},{transform:'scale(1.03) rotate(2deg)'},{transform:'scale(1)'}],{duration:220});};
function resize(){const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(innerWidth*dpr);canvas.height=Math.round(innerHeight*dpr);}window.addEventListener('resize',resize);resize();
canvas.addEventListener('contextmenu',e=>e.preventDefault());
canvas.addEventListener('mousedown',e=>{if(!playing||paused||state?.ended)return;e.preventDefault();audioOn();if(!mouseLocked()){captureMouse();return;}if(e.button===0)fire=true;if(e.button===2)beginSuper('Mouse2');});
window.addEventListener('mouseup',e=>{if(e.button===0)fire=false;if(e.button===2)releaseSuper('Mouse2');});canvas.addEventListener('pointercancel',resetInput);
window.addEventListener('keydown',e=>{if(e.target instanceof HTMLInputElement||e.target instanceof HTMLSelectElement||e.target instanceof HTMLTextAreaElement)return;if(e.code==='Escape'){e.preventDefault();if(performance.now()-lockLostAt<150)return;if(!$('recruitModal').hidden){$('closeRecruit').onclick();return;}if(!$('dropModal').hidden){$('closeDrop').onclick();return;}if(!$('roadModal').hidden){modal('roadModal',false);return;}if(!$('metaModal').hidden){modal('metaModal',false);return;}if(!$('helpModal').hidden)modal('helpModal',false);else if(searching)$('cancelQueue').onclick();else togglePause();return;}if(!playing||paused||!mouseLocked()||state?.ended)return;if(['KeyW','KeyA','KeyS','KeyD','KeyQ','KeyE','KeyF'].includes(e.code)){e.preventDefault();keys.add(e.code);audioOn();if(!e.repeat){if(e.code==='KeyQ')beginSuper('KeyQ');if(e.code==='KeyE')latched.gadget=performance.now()+100;if(e.code==='KeyF'&&Z.hasHyper(aimActor()))latched.hyper=performance.now()+100;}}});
window.addEventListener('keyup',e=>{keys.delete(e.code);if(e.code==='KeyQ')releaseSuper('KeyQ');});
window.addEventListener('blur',()=>{resetInput();if(playing&&!paused&&!state?.ended)togglePause();});document.addEventListener('visibilitychange',()=>{if(document.hidden){resetInput();if(playing&&!paused&&!state?.ended)togglePause();}});
$('gadgetBtn').onclick=()=>{if(playing&&!paused&&mouseLocked())latched.gadget=performance.now()+100;};
$('hyperBtn').onclick=()=>{if(playing&&!paused&&mouseLocked()&&Z.hasHyper(aimActor()))latched.hyper=performance.now()+100;};
$('superBtn').onpointerdown=()=>beginSuper('button');window.addEventListener('pointerup',()=>releaseSuper('button'));

function hud(now){const p=state.players.find(q=>q.id===myId);if(!p)return;if(!p.alive){superAim=null;queuedSuper=null;superSources.clear();fire=false;}const c=Z.stats(p.fighter,Z.lv(p)),md=Z.mode(state.mode),m=state.mode,timed=m==='zone'?180-state.time:m==='bounty'||m==='soccer'?150-state.time:md.roundTime?md.roundTime-state.roundTime:state.time,seconds=Math.max(0,Math.ceil(timed));$('clock').textContent=Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');
 const alive=md.showdown?new Set(state.players.filter(q=>!state.placement?.[q.team]).map(q=>q.team)).size:0;
 $('blueScore').textContent=m==='zone'?Math.floor(state.score[0])+'%':md.roundTime?state.roundWins[0]:md.showdown?'⚡'+(p.cubes||0):md.training?'—':state.score[0];
 $('orangeScore').textContent=m==='zone'?Math.floor(state.score[1])+'%':md.roundTime?state.roundWins[1]:md.showdown?alive+' LEFT':md.training?'—':state.score[1];
 $('roundLabel').textContent=m==='zone'?(state.zoneState===2?'CONTESTED':state.zoneState===p.team?'YOUR TEAM HOLDS THE ZONE':'CONTROL THE ZONE'):md.roundTime?'ROUND '+state.round+' · FIRST TO 2':m==='gems'?(state.gemLeader>=0?(state.gemLeader===0?'BLUE':'ORANGE')+' WINS IN '+Math.ceil(state.gemTimer)+'s':'HOLD 10 GEMS FOR 15s'):m==='bounty'?'FIRST TO 20 STARS':m==='soccer'?'FIRST TO 2 GOALS':md.showdown?(state.gasR?'POISON GAS CLOSING':'BREAK BOXES · COLLECT CUBES'):'TRAINING · NO TROPHIES';
 $('connection').textContent=online?'LIVE · '+ping+' ms':'PRACTICE · LOCAL';$('selfRole').textContent=c.role.toUpperCase()+' · LEVEL '+p.level+(p.cubes?' +'+p.cubes+' ⚡':'');$('healthFill').style.width=100*p.hp/p.maxHP+'%';$('healthText').textContent=Math.ceil(p.hp)+' / '+p.maxHP+' HP';for(const [n,el]of [...$('ammo').children].entries())el.style.opacity=String(.18+.82*Z.clamp(p.ammo-n,0,1));const g=c.gadgets[p.gadget];$('gadgetName').textContent=g?g.name:'GADGET LOCKED';$('gadgetStatus').textContent=!g?p.level<Z.GADGET_LEVELS[0]?'UNLOCK AT LEVEL '+Z.GADGET_LEVELS[0]:'BUY A GADGET IN THE MENU':p.gadgetCD>0?Math.ceil(p.gadgetCD)+'s COOLDOWN':'READY';$('gadgetFill').style.width=(g?100*(1-p.gadgetCD/g.cd):0)+'%';$('gadgetBtn').disabled=!g;$('gadgetBtn').classList.toggle('ready',!!g&&p.gadgetCD<=0&&p.alive);$('abilityName').textContent=c.super;$('superStatus').textContent=superAim?'RELEASE TO CAST':p.charge>=100?'HOLD Q / RIGHT CLICK TO AIM':Math.floor(p.charge)+'% CHARGED';$('superFill').style.width=p.charge+'%';$('superBtn').classList.toggle('ready',p.charge>=100&&p.alive);$('hyperStatus').textContent=!Z.hasHyper(p)?(p.level<Z.MAX_LEVEL?'LOCKED · LEVEL '+Z.MAX_LEVEL:'BUY IN MENU · 2,500 COINS'):p.hyperTime>0?'ACTIVE · '+Math.ceil(p.hyperTime)+'s':p.hyperCharge>=100?'READY · F':Math.floor(p.hyperCharge||0)+'% · COMBAT CHARGE';$('hyperFill').style.width=(p.hyperTime>0?100*p.hyperTime/Z.HYPER_DURATION:p.hyperCharge||0)+'%';$('hyperBtn').disabled=!Z.hasHyper(p)||!p.alive||p.hyperTime>0||(p.hyperCharge||0)<100;$('hyperBtn').classList.toggle('ready',Z.hasHyper(p)&&p.hyperCharge>=100&&p.alive);$('hyperBtn').classList.toggle('active',p.hyperTime>0);$('teamStatus').replaceChildren();for(const q of state.players.filter(q=>q.team===p.team)){const row=document.createElement('div');row.className='team-member'+(!q.alive?' out':'');const name=document.createElement('span'),dot=document.createElement('i');name.append(dot,document.createTextNode(q.name));const hp=document.createElement('span');hp.textContent=q.alive?Math.round(q.hp/q.maxHP*100)+'%':q.respawn>0?'↺ '+Math.ceil(q.respawn)+'s':'OUT';row.append(name,hp);$('teamStatus').append(row);}
 $('deathInfo').hidden=p.alive||state.ended;$('deathInfo').textContent=p.respawn>0?'Back in '+Math.max(1,Math.ceil(p.respawn))+'…':md.showdown?'Eliminated.':'Out this round. Your team is still in.';
 $('banner').textContent=state.phase==='countdown'?String(Math.max(1,Math.ceil(state.timer))):state.phase==='intermission'?(state.lastRoundWinner===null?'Round drawn.':(state.mode==='soccer'?'GOAL!':state.lastRoundWinner===p.team?'Round secured.':'Round lost.')) :'';
 for(const e of state.events){if(e.id<=lastEvent)continue;lastEvent=e.id;sound(e);}
}
function render(now,dt){ctx.setTransform(1,0,0,1,0,0);ctx.fillStyle='#153039';ctx.fillRect(0,0,canvas.width,canvas.height);if(!playing||!state){const k=Math.max(canvas.width/Z.W,canvas.height/Z.H);ctx.save();ctx.translate((canvas.width-Z.W*k)/2,(canvas.height-Z.H*k)/2);ctx.scale(k,k);ctx.drawImage(A.terrain(battle),0,0);ctx.restore();return;}
 const dpr=Math.min(devicePixelRatio||1,2),padTop=96*dpr,padBottom=126*dpr,scale=Math.min((canvas.width-35*dpr)/Z.W,(canvas.height-padTop-padBottom)/Z.H),safeScale=Math.max(.2,scale);transform={scale:safeScale,x:(canvas.width-Z.W*safeScale)/2,y:padTop+(canvas.height-padTop-padBottom-Z.H*safeScale)/2};ctx.save();ctx.translate(transform.x,transform.y);ctx.scale(safeScale,safeScale);ctx.beginPath();ctx.roundRect(0,0,Z.W,Z.H,18);ctx.clip();
 let display=state;if(online){const elapsed=Math.min(.07,(now-snapshotAt)/1000);correction.x*=Math.exp(-dt*16);correction.y*=Math.exp(-dt*16);display={...state,players:state.players.map(p=>{if(p.hidden)return p;let v=views.get(p.id);const local=p.id===myId&&predicted,target=local?predicted:p,tx=target.x+(local?correction.x:(p.vx||0)*elapsed),ty=target.y+(local?correction.y:(p.vy||0)*elapsed);if(!v||Math.hypot(v.x-tx,v.y-ty)>140||local)v={x:tx,y:ty};else{const k=1-Math.exp(-dt*23);v.x+=(tx-v.x)*k;v.y+=(ty-v.y)*k;}views.set(p.id,v);return {...p,x:v.x,y:v.y,aimingSuper:local?!!superAim:p.aimingSuper,angle:local?Math.atan2(mouse.y-v.y,mouse.x-v.x):p.angle,run:(target.run||0)+(local?0:Math.hypot(p.vx||0,p.vy||0)*elapsed/50)};})};}
 const me=display.players.find(q=>q.id===myId),mw=state.W||Z.W,mh=state.H||Z.H;if(me&&me.x!=null&&me.alive){cam.x=mw>Z.W?Z.clamp(me.x-Z.W/2,0,mw-Z.W):(mw-Z.W)/2;cam.y=mh>Z.H?Z.clamp(me.y-Z.H/2,0,mh-Z.H):(mh-Z.H)/2;}if(me&&me.x!=null&&me.alive)updateAim(me);ctx.translate(-cam.x,-cam.y);A.scene(ctx,display,now/1000,myId,paused?null:mouse,dt);ctx.restore();}
function frame(now){if(now-dailyAt>1000){dailyAt=now;if(playType==='ranked'&&!playing)$('modeDescription').textContent=rankedText();if(E.touchDay(profile)){save();refreshEconomy();}}const dt=Math.min(.12,Math.max(0,(now-last)/1000));last=now;if(playing&&state){if(!state.ended){if(!paused||online){acc=Math.min(.16,acc+dt);while(acc>=Z.DT){const i=paused?{}:currentInput(now);if(online){const command={seq:++seq,input:i};pending.push(command);if(pending.length>90)pending.shift();if(predicted)Z.predict(state,predicted,i);send({type:'input',...command});}else Z.step(state,{[myId]:i});acc-=Z.DT;}}if(online&&now-pingAt>2000){send({type:'ping',at:now});pingAt=now;}}hud(now);if(state.ended)showResult();}render(now,dt);requestAnimationFrame(frame);}
selectMode(battle);chooseFighter(selected);requestAnimationFrame(frame);
